-- Export-only catalog; does not contain player data.
BEGIN;
CREATE TABLE IF NOT EXISTS "game_content" ("category" TEXT NOT NULL, "item_key" TEXT NOT NULL, "payload" TEXT NOT NULL, PRIMARY KEY ("category","item_key"));
CREATE TABLE IF NOT EXISTS "game_content_links" ("category" TEXT NOT NULL, "item_key" TEXT NOT NULL, "relation" TEXT NOT NULL, "target_category" TEXT NOT NULL, "target_key" TEXT NOT NULL, PRIMARY KEY ("category","item_key","relation"), FOREIGN KEY ("category","item_key") REFERENCES "game_content"("category","item_key"), FOREIGN KEY ("target_category","target_key") REFERENCES "game_content"("category","item_key"));
DELETE FROM game_content_links;
DELETE FROM game_content;
COMMIT;
